INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4573731, 659546, 91314, '<td valign="top">Job well done in portraying a photographer in her environment.</td>', 'Job well done in portraying a photographer in her environment.', '2008-03-19 11:22:34.000000', NULL, 1),
(4573732, 658826, 91314, '<td valign="top">Nice contrast and a good close up.  Really shows the innocents and freakles.</td>', 'Nice contrast and a good close up.  Really shows the innocents and freakles.', '2008-03-19 11:22:36.000000', NULL, 1),
(4573733, 659243, 91314, '<td valign="top">Good job in showing subject within his environment. Good contrast also.</td>', 'Good job in showing subject within his environment. Good contrast also.', '2008-03-19 11:22:39.000000', NULL, 1),
(4573735, 659636, 91314, '<td valign="top">Good close up and the black and white gives it a sophisticated feel.</td>', 'Good close up and the black and white gives it a sophisticated feel.', '2008-03-19 11:22:48.000000', NULL, 1),
(4573736, 659388, 91314, '<td valign="top">God job in capturing the new talent for this generation. Totally focused!</td>', 'God job in capturing the new talent for this generation. Totally focused!', '2008-03-19 11:22:56.000000', NULL, 1),
(4573737, 659171, 91314, '<td valign="top">It would have made this picture even better if I could have seen the kids not blurred.</td>', 'It would have made this picture even better if I could have seen the kids not blurred.', '2008-03-19 11:23:00.000000', NULL, 1),
(4573749, 659060, 9462, '<td valign="top">blah blah blah, yeah talking instead of doing. <br/>I hate politicians... and yes, you''ve captured what they do best.</td>', 'blah blah blah, yeah talking instead of doing. I hate politicians... and yes, you''ve captured what they do best.', '2008-03-19 11:27:54.000000', NULL, 1),
(4573752, 658091, 51538, '<td valign="top">I know that man.  An Englishman in NYC and rather famous too.  Those Swiss made peelers really work well.  I have two ;-)  You made a fine portrait there.  Really captured his essence.</td>', 'I know that man.  An Englishman in NYC and rather famous too.  Those Swiss made peelers really work well.  I have two ;-)  You made a fine portrait there.  Really captured his essence.', '2008-03-19 11:27:59.000000', NULL, 1),
(4573788, 657575, 58691, '<td valign="top">This is a good shot, but I think the processing is overdone. It appears to me that all the definition of the shot has been smoothed out. What would be dirt on their faces now appears to be complexion. The piece of equipment looks waxy or polished - unreal. The vignetting doesn''t help the image either.</td>', 'This is a good shot, but I think the processing is overdone. It appears to me that all the definition of the shot has been smoothed out. What would be dirt on their faces now appears to be complexion. The piece of equipment looks waxy or polished - unreal. The vignetting doesn''t help the image either.', '2008-03-19 11:40:51.000000', NULL, 1),
(4573798, 659063, 33672, '<td valign="top">Best in theme. Nice attention to detail.</td>', 'Best in theme. Nice attention to detail.', '2008-03-19 11:43:12.000000', NULL, 1),
(4573810, 658951, 91314, '<td valign="top">This photo is pixilated, not good quality.</td>', 'This photo is pixilated, not good quality.', '2008-03-19 11:47:35.000000', NULL, 1),
(4573813, 658115, 58691, '<td valign="top">Better lighting on the subject would help this shot out. Cute kid and cute expression on this face, but the overall image is a bit muddled.</td>', 'Better lighting on the subject would help this shot out. Cute kid and cute expression on this face, but the overall image is a bit muddled.', '2008-03-19 11:49:44.000000', NULL, 1),
(4573816, 657185, 61958, '<td valign="top">Focus seems a little off... and even though this is environmental I''d still like to have seen more of the subject and less trees</td>', 'Focus seems a little off... and even though this is environmental I''d still like to have seen more of the subject and less trees', '2008-03-19 11:50:39.000000', NULL, 1),
(4573818, 659666, 66515, '<td valign="top">A little heavy on the PP in my opinion</td>', 'A little heavy on the PP in my opinion', '2008-03-19 11:51:49.000000', NULL, 1),
(4573820, 658342, 61958, '<td valign="top">This is missing much of the environment, without the title one wouldn''t be able to tell much about her at all</td>', 'This is missing much of the environment, without the title one wouldn''t be able to tell much about her at all', '2008-03-19 11:52:35.000000', NULL, 1),
(4573823, 659585, 66515, '<td valign="top">Needs a bit more contrast as it looks (for lack of a better term) "muddy". Pun not intended.</td>', 'Needs a bit more contrast as it looks (for lack of a better term) "muddy". Pun not intended.', '2008-03-19 11:53:51.000000', NULL, 1),
