(4573830, 659632, 61958, '<td valign="top">Far too harsh and mostly blown out. I''m not sure what you were trying for, but the result is not a pleasing portrait.</td>', 'Far too harsh and mostly blown out. I''m not sure what you were trying for, but the result is not a pleasing portrait.', '2008-03-19 11:55:58.000000', NULL, 1),
(4573831, 658171, 61958, '<td valign="top">this shot does not tell me much about her envoronment other than she''s in a toy car. also I would have liked to see her eyes gazing towards the camera rather than away.</td>', 'this shot does not tell me much about her envoronment other than she''s in a toy car. also I would have liked to see her eyes gazing towards the camera rather than away.', '2008-03-19 11:56:06.000000', NULL, 1),
