(4573897, 659063, 84124, '<td valign="top">very creative take on the challenge.  the "environment" is a bit bare, but still a good shot.</td>', 'very creative take on the challenge.  the "environment" is a bit bare, but still a good shot.', '2008-03-19 12:15:01.000000', NULL, 1),
