(4573921, 659257, 58691, '<td valign="top">Good choice of duotone with this. I think is one of the few true environmental portraits I''ve come across in this challenge to this point.</td>', 'Good choice of duotone with this. I think is one of the few true environmental portraits I''ve come across in this challenge to this point.', '2008-03-19 12:19:30.000000', NULL, 1),
(4573925, 658709, 84124, '<td valign="top">Whaddyu lookin'' at???  Nice portrait, this will do well.</td>', 'Whaddyu lookin'' at???  Nice portrait, this will do well.', '2008-03-19 12:20:16.000000', NULL, 1),
(4573928, 658964, 58691, '<td valign="top">I don''t see how this is a portrait in any way.</td>', 'I don''t see how this is a portrait in any way.', '2008-03-19 12:20:29.000000', NULL, 1),
