(4573945, 659688, 84124, '<td valign="top">This is a cool action shot.  the environment is bare, but not sure if you need much, flying high over your camera is usually enough for the viewer to get the point.</td>', 'This is a cool action shot.  the environment is bare, but not sure if you need much, flying high over your camera is usually enough for the viewer to get the point.', '2008-03-19 12:25:03.000000', NULL, 1),
(4573948, 659545, 84124, '<td valign="top">The portrait is spot on, but the blurriness detracts from his "environment"</td>', 'The portrait is spot on, but the blurriness detracts from his "environment"', '2008-03-19 12:25:39.000000', NULL, 1),
(4573950, 658939, 84124, '<td valign="top">Darkness of the portrait detracts from the photo, environment of the subject is beautiful however.</td>', 'Darkness of the portrait detracts from the photo, environment of the subject is beautiful however.', '2008-03-19 12:26:40.000000', NULL, 1),
(4573953, 658316, 58691, '<td valign="top">A decent portrait of the chicken, but the environment doesn''t compliment the subject.</td>', 'A decent portrait of the chicken, but the environment doesn''t compliment the subject.', '2008-03-19 12:27:04.000000', NULL, 1),
