(4573982, 659522, 84124, '<td valign="top">Portrait is spot on, but surroundings very bare.</td>', 'Portrait is spot on, but surroundings very bare.', '2008-03-19 12:34:46.000000', NULL, 1),
(4573983, 658909, 66353, '<td valign="top">Portrait? Not in my book...</td>', 'Portrait? Not in my book...', '2008-03-19 12:35:00.000000', NULL, 1),
