(4574072, 659388, 84124, '<td valign="top">Another great take on the challenge, although your subject on the left detracts from your subject on the rights intensity and focus.  Regardless, this is a fantastic portrait.</td>', 'Another great take on the challenge, although your subject on the left detracts from your subject on the rights intensity and focus.  Regardless, this is a fantastic portrait.', '2008-03-19 12:55:57.000000', NULL, 1),
(4574079, 659238, 58691, '<td valign="top">I am not sure how this fits the challenge at all. The intent of a portrait, usually, is to display the likeness, personality, and even the mood of the person. In an environmental portrait, the environment should help define the placement/occupation/status of the subject.</td>', 'I am not sure how this fits the challenge at all. The intent of a portrait, usually, is to display the likeness, personality, and even the mood of the person. In an environmental portrait, the environment should help define the placement/occupation/status of the subject.', '2008-03-19 12:57:59.000000', NULL, 1),
