(4574316, 658717, 18563, '<td valign="top">Nice shot...pardon the pun. Using Noise Ninja or some other noise reduction software would have really helped here</td>', 'Nice shot...pardon the pun. Using Noise Ninja or some other noise reduction software would have really helped here', '2008-03-19 14:00:37.000000', NULL, 1),
(4574317, 659061, 89341, '<td valign="top">The colours are very good, I think I''d have liked the couple slight more in the shot maybe, but still a great picture</td>', 'The colours are very good, I think I''d have liked the couple slight more in the shot maybe, but still a great picture', '2008-03-19 14:00:42.000000', NULL, 1),
(4574322, 659391, 18563, '<td valign="top">Haha! Great capture! a little busy and noisy</td>', 'Haha! Great capture! a little busy and noisy', '2008-03-19 14:02:42.000000', NULL, 1),
(4574326, 658826, 89341, '<td valign="top">Nice portrait but I think I''d like to see a little of her environment</td>', 'Nice portrait but I think I''d like to see a little of her environment', '2008-03-19 14:03:33.000000', NULL, 1),
(4574328, 659146, 18563, '<td valign="top">Would have been a little better if there was something in the background to tell us something about the subject. Nice capture of his expression though</td>', 'Would have been a little better if there was something in the background to tell us something about the subject. Nice capture of his expression though', '2008-03-19 14:03:49.000000', NULL, 1),
(4574331, 659238, 89341, '<td valign="top">Unless I''m wrong a portrait is of something living, a person or pet</td>', 'Unless I''m wrong a portrait is of something living, a person or pet', '2008-03-19 14:04:51.000000', NULL, 1),
(4574332, 658684, 18563, '<td valign="top">Great shot but its so noisy. Try using a diff ISO setting or Noise Ninja (or equivilant software) to reduce the noise.</td>', 'Great shot but its so noisy. Try using a diff ISO setting or Noise Ninja (or equivilant software) to reduce the noise.', '2008-03-19 14:05:10.000000', NULL, 1),
(4574335, 659461, 18563, '<td valign="top">My favorite picture of this challenge! Well done!!!</td>', 'My favorite picture of this challenge! Well done!!!', '2008-03-19 14:07:35.000000', NULL, 1),
(4574337, 659359, 18563, '<td valign="top">Great macro shot!</td>', 'Great macro shot!', '2008-03-19 14:08:11.000000', NULL, 1),
(4574338, 659688, 18563, '<td valign="top">This is a great action shot! Way to meet the challenge. 7</td>', 'This is a great action shot! Way to meet the challenge. 7', '2008-03-19 14:08:55.000000', NULL, 1),
(4574340, 658143, 89341, '<td valign="top">I think the composition would be slightly better with the guy behind not being in the shot ... also the fact he is on the phone is a little distracting .. meets challenge well though</td>', 'I think the composition would be slightly better with the guy behind not being in the shot ... also the fact he is on the phone is a little distracting .. meets challenge well though', '2008-03-19 14:09:30.000000', NULL, 1),
(4574342, 659632, 58691, '<td valign="top">This almost appears to have a stamp filter effect on it and the processing does give it some artistic merit, but it is awfully harsh in contrast.</td>', 'This almost appears to have a stamp filter effect on it and the processing does give it some artistic merit, but it is awfully harsh in contrast.', '2008-03-19 14:09:47.000000', NULL, 1),
(4574344, 658091, 18563, '<td valign="top">This is a great shot...i could stare at it for hours! Deff meets the challenge.</td>', 'This is a great shot...i could stare at it for hours! Deff meets the challenge.', '2008-03-19 14:10:29.000000', NULL, 1),
(4574345, 657878, 89341, '<td valign="top">Nice compostion</td>', 'Nice compostion', '2008-03-19 14:10:31.000000', NULL, 1),
(4574347, 659361, 18563, '<td valign="top">The wide angle really brings out your subjects character. Great! 7</td>', 'The wide angle really brings out your subjects character. Great! 7', '2008-03-19 14:11:16.000000', NULL, 1),
(4574349, 659443, 58691, '<td valign="top">Great shot. Has a bit of Dr. Seuss feel to it. This is very good editing if you stayed w/in the confines of the basic editing rules.</td>', 'Great shot. Has a bit of Dr. Seuss feel to it. This is very good editing if you stayed w/in the confines of the basic editing rules.', '2008-03-19 14:11:26.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4574352, 657219, 89341, '<td valign="top">Not really a portrait IMHO ... nice enough photo though</td>', 'Not really a portrait IMHO ... nice enough photo though', '2008-03-19 14:12:02.000000', NULL, 1),
(4574353, 659635, 18563, '<td valign="top">This shot is GREAT! Love the clear reflection!!! Hands down one of my favorites!</td>', 'This shot is GREAT! Love the clear reflection!!! Hands down one of my favorites!', '2008-03-19 14:12:25.000000', NULL, 1),
(4574355, 659546, 18563, '<td valign="top">Very creative! well composed! 8</td>', 'Very creative! well composed! 8', '2008-03-19 14:12:54.000000', NULL, 1),
(4574356, 659610, 18563, '<td valign="top">I really like this shot..nice angle, great use of a slower shutter speed to capture the action. Subject could have been a little darker but that is just me. 7</td>', 'I really like this shot..nice angle, great use of a slower shutter speed to capture the action. Subject could have been a little darker but that is just me. 7', '2008-03-19 14:13:17.000000', NULL, 1),
(4574359, 659470, 89341, '<td valign="top">Nice colours, it''s a shame about the shadow over his face</td>', 'Nice colours, it''s a shame about the shadow over his face', '2008-03-19 14:13:46.000000', NULL, 1),
(4574362, 659217, 18197, '<td valign="top">Fantastic bike! This would be more interesting against a more photogenic background.</td>', 'Fantastic bike! This would be more interesting against a more photogenic background.', '2008-03-19 14:14:48.000000', NULL, 1),
(4574369, 659666, 58691, '<td valign="top">The HDR processing makes this rather unreal and cartoonish. The baseline image looks like it was a good shot.</td>', 'The HDR processing makes this rather unreal and cartoonish. The baseline image looks like it was a good shot.', '2008-03-19 14:19:35.000000', NULL, 1),
(4574370, 659551, 89341, '<td valign="top">Nice photo, I think if the priest was closed and off to one side it would be slightly better</td>', 'Nice photo, I think if the priest was closed and off to one side it would be slightly better', '2008-03-19 14:19:51.000000', NULL, 1),
(4574371, 658557, 89341, '<td valign="top">a little too dark IMHO</td>', 'a little too dark IMHO', '2008-03-19 14:20:16.000000', NULL, 1),
(4574373, 659114, 89341, '<td valign="top">The golf karts in the background are a little distracting, I also would like to see his face I think ... nice enough though</td>', 'The golf karts in the background are a little distracting, I also would like to see his face I think ... nice enough though', '2008-03-19 14:21:40.000000', NULL, 1),
(4574374, 659666, 18197, '<td valign="top">Too far with the HDR in my opinion. Otherwise well imagined, composed and shot.</td>', 'Too far with the HDR in my opinion. Otherwise well imagined, composed and shot.', '2008-03-19 14:21:41.000000', NULL, 1),
(4574378, 658877, 89341, '<td valign="top">Nice photo but I think you may have missed the challenge as to me a portrait is of a person (or animal) ...</td>', 'Nice photo but I think you may have missed the challenge as to me a portrait is of a person (or animal) ...', '2008-03-19 14:23:07.000000', NULL, 1),
(4574381, 659688, 89341, '<td valign="top">Fantastic capture, best I''ve seen so far</td>', 'Fantastic capture, best I''ve seen so far', '2008-03-19 14:24:05.000000', NULL, 1),
(4574385, 658710, 58691, '<td valign="top">The lighting is kind of flat on this, but I like the angle and she is adorable. For Envir. Portrait, it would be better to see her amongst the flowers and plants instead of just holding them.</td>', 'The lighting is kind of flat on this, but I like the angle and she is adorable. For Envir. Portrait, it would be better to see her amongst the flowers and plants instead of just holding them.', '2008-03-19 14:25:57.000000', NULL, 1),
(4574387, 658907, 89341, '<td valign="top">Nice sharp image, I think I''d like to see more of his environment though ... maybe a couple of audience members or a mic or something</td>', 'Nice sharp image, I think I''d like to see more of his environment though ... maybe a couple of audience members or a mic or something', '2008-03-19 14:26:55.000000', NULL, 1),
(4574391, 658793, 89763, '<td valign="top">nice shot, but not showing much of the environment</td>', 'nice shot, but not showing much of the environment', '2008-03-19 14:31:18.000000', NULL, 1),
(4574392, 658474, 89763, '<td valign="top">DNMC - Where''s the environment?</td>', 'DNMC - Where''s the environment?', '2008-03-19 14:31:49.000000', NULL, 1),
(4574394, 659511, 89763, '<td valign="top">nice expression, good compo. It''s great except that bright spot on his head. 7</td>', 'nice expression, good compo. It''s great except that bright spot on his head. 7', '2008-03-19 14:32:49.000000', NULL, 1),
(4574397, 658239, 89763, '<td valign="top">very unique, interesting; love the details in the face and hair. the woman''s clothing seems washed out, though, and I can''t really see their environment.</td>', 'very unique, interesting; love the details in the face and hair. the woman''s clothing seems washed out, though, and I can''t really see their environment.', '2008-03-19 14:33:45.000000', NULL, 1),
(4574398, 659047, 89763, '<td valign="top">Not much environment here</td>', 'Not much environment here', '2008-03-19 14:34:05.000000', NULL, 1),
(4574402, 659069, 89763, '<td valign="top">nice lighting -  that and all the open books help give that late-night cramming feel.</td>', 'nice lighting -  that and all the open books help give that late-night cramming feel.', '2008-03-19 14:34:56.000000', NULL, 1),
(4574403, 659551, 18197, '<td valign="top">As well as any photo in the challenge, you''ve caught the person in their environment and given us a beautiful portrait in the bargan. Very well composed, captured and edited.</td>', 'As well as any photo in the challenge, you''ve caught the person in their environment and given us a beautiful portrait in the bargan. Very well composed, captured and edited.', '2008-03-19 14:35:11.000000', NULL, 1),
(4574404, 658951, 89763, '<td valign="top">seems noisy to me. nice compo and dof though.</td>', 'seems noisy to me. nice compo and dof though.', '2008-03-19 14:35:21.000000', NULL, 1),
(4574405, 658418, 89763, '<td valign="top">don''t see much environment, but nice dramatic lighting.</td>', 'don''t see much environment, but nice dramatic lighting.', '2008-03-19 14:36:17.000000', NULL, 1),
(4574408, 659635, 89763, '<td valign="top">This definitely speaks to the challenge. I love the use of the chrome to reflect the environment - it adds a unique quality to this image. 9</td>', 'This definitely speaks to the challenge. I love the use of the chrome to reflect the environment - it adds a unique quality to this image. 9', '2008-03-19 14:37:32.000000', NULL, 1),
(4574412, 657935, 58691, '<td valign="top">Odd processing on this one - it looks as though a noise reduction process was a bit overdone. I love the expression on the subject''s face and the red hose is rather <strike>strategically</strike> uniquely placed.</td>', 'Odd processing on this one - it looks as though a noise reduction process was a bit overdone. I love the expression on the subject''s face and the red hose is rather strategically uniquely placed.', '2008-03-19 14:38:05.000000', NULL, 1),
(4574413, 657219, 89763, '<td valign="top">Is this a portait of a boat? DNMC, IMO. But, I like the compo and lighting of this image.</td>', 'Is this a portait of a boat? DNMC, IMO. But, I like the compo and lighting of this image.', '2008-03-19 14:38:17.000000', NULL, 1),
(4574415, 659461, 18197, '<td valign="top">Probably not the best execution of all the photos in the challenge, but of all the entries in the challenge, this feels most like a portrait and you''ve clearly caught a player in his environment. I especially like the composition. The top 2/3 of the frame form a square bisected by the strong diagonal. Catching the reflection is perfect. The bottom 1/3 gives us the context. Perfect. Well done! Best of show!</td>', 'Probably not the best execution of all the photos in the challenge, but of all the entries in the challenge, this feels most like a portrait and you''ve clearly caught a player in his environment. I especially like the composition. The top 2/3 of the frame form a square bisected by the strong diagonal. Catching the reflection is perfect. The bottom 1/3 gives us the context. Perfect. Well done! Best of show!', '2008-03-19 14:39:04.000000', NULL, 1),
(4574417, 659483, 19708, '<td valign="top">A sharper image here would have really helped this a lot.<br/>I do like the depth of field and the nature of the portrait.</td>', 'A sharper image here would have really helped this a lot.I do like the depth of field and the nature of the portrait.', '2008-03-19 14:39:12.000000', NULL, 1),
(4574420, 658829, 89763, '<td valign="top">Wow! That''s one neat teenager!! The inclusion of the earphones and laptop really make this shot. I like the way the light from the laptop puts her in the spotlight. Great colors, as well.</td>', 'Wow! That''s one neat teenager!! The inclusion of the earphones and laptop really make this shot. I like the way the light from the laptop puts her in the spotlight. Great colors, as well.', '2008-03-19 14:40:10.000000', NULL, 1),
(4574421, 658907, 19708, '<td valign="top">Not much in his "environment" to suggest where it was taken. Looks too much like a studio kind of shot really.<br/>A stage, crowd, etc in the background would have done this much better justice.</td>', 'Not much in his "environment" to suggest where it was taken. Looks too much like a studio kind of shot really.A stage, crowd, etc in the background would have done this much better justice.', '2008-03-19 14:40:45.000000', NULL, 1),
(4574422, 658964, 19708, '<td valign="top">Not much in the way of a portrait really. More of an activity shot.</td>', 'Not much in the way of a portrait really. More of an activity shot.', '2008-03-19 14:41:17.000000', NULL, 1),
(4574424, 659490, 89763, '<td valign="top">I think there''s supposed to be a person in this portrait challenge, but I love this image anyway, with the angled perspective and the interesting sky. The branches from another tree on the left are somewhat distracting, though.</td>', 'I think there''s supposed to be a person in this portrait challenge, but I love this image anyway, with the angled perspective and the interesting sky. The branches from another tree on the left are somewhat distracting, though.', '2008-03-19 14:41:42.000000', NULL, 1),
(4574425, 659443, 19708, '<td valign="top">Great lighting on this one and love the color pop the red does for it.</td>', 'Great lighting on this one and love the color pop the red does for it.', '2008-03-19 14:42:04.000000', NULL, 1),
(4574427, 657878, 58691, '<td valign="top">Excellent job - good shot - composition, exposure, lighting - all very well done. This fits the challenge perfectly, unlike many of the entries in this challenge. I hope you get a ribbon for this.</td>', 'Excellent job - good shot - composition, exposure, lighting - all very well done. This fits the challenge perfectly, unlike many of the entries in this challenge. I hope you get a ribbon for this.', '2008-03-19 14:42:25.000000', NULL, 1),
(4574428, 658522, 19708, '<td valign="top">Well done. This has everything going for it - great lighting, a nice smile and good composition.</td>', 'Well done. This has everything going for it - great lighting, a nice smile and good composition.', '2008-03-19 14:42:58.000000', NULL, 1),
(4574429, 658286, 19708, '<td valign="top">Nicely done here. The background supports his environment well.</td>', 'Nicely done here. The background supports his environment well.', '2008-03-19 14:43:35.000000', NULL, 1),
(4574430, 658286, 89763, '<td valign="top">Nice expression you captured. I like how the background is slightly oof, so that you can still recognize what everything is. I''d only suggest cropping in more of the top, maybe almost down to the top of the front seat.</td>', 'Nice expression you captured. I like how the background is slightly oof, so that you can still recognize what everything is. I''d only suggest cropping in more of the top, maybe almost down to the top of the front seat.', '2008-03-19 14:43:36.000000', NULL, 1),
(4574432, 658676, 19708, '<td valign="top">Nicely done here. The story is being well told here.</td>', 'Nicely done here. The story is being well told here.', '2008-03-19 14:44:05.000000', NULL, 1),
(4574434, 658264, 19708, '<td valign="top">What a mess! (in a good way)<br/>First thought was they tore up some pillows and was a feather frenzy there.</td>', 'What a mess! (in a good way)First thought was they tore up some pillows and was a feather frenzy there.', '2008-03-19 14:45:00.000000', NULL, 1),
(4574437, 658091, 89763, '<td valign="top">Your subject is very welcoming. What''s he doing? Shredding carrots? Is he selling something? This image really piques my interest. It''s framed very nicely, telling something about the woman in the background too. You hit the challenge right on!</td>', 'Your subject is very welcoming. What''s he doing? Shredding carrots? Is he selling something? This image really piques my interest. It''s framed very nicely, telling something about the woman in the background too. You hit the challenge right on!', '2008-03-19 14:45:47.000000', NULL, 1),
(4574439, 659235, 89763, '<td valign="top">The emu is oof. It almost looks fake.</td>', 'The emu is oof. It almost looks fake.', '2008-03-19 14:46:20.000000', NULL, 1),
(4574441, 658908, 19708, '<td valign="top">Nicely done here. The background supports his environment well.<br/>I think just a little tighter crop may have helped take a lot of the focal point off of his belly away, but then the glove would have been lost showing in the background.</td>', 'Nicely done here. The background supports his environment well.I think just a little tighter crop may have helped take a lot of the focal point off of his belly away, but then the glove would have been lost showing in the background.', '2008-03-19 14:46:37.000000', NULL, 1),
(4574446, 657219, 19708, '<td valign="top">hmmm. OK, the boat is the subject of the portrait and is shown in it''s environment. A bit out of the box, and certainly creative.</td>', 'hmmm. OK, the boat is the subject of the portrait and is shown in it''s environment. A bit out of the box, and certainly creative.', '2008-03-19 14:48:14.000000', NULL, 1),
(4574447, 659114, 89763, '<td valign="top">Looks a bit overexposed. I''d like to see more of the subject''s face. Also, it''s not clear what the environment is - he''s walking with a horse (farm? riding classes?) but there are golf carts in the background (golf course?)...</td>', 'Looks a bit overexposed. I''d like to see more of the subject''s face. Also, it''s not clear what the environment is - he''s walking with a horse (farm? riding classes?) but there are golf carts in the background (golf course?)...', '2008-03-19 14:48:30.000000', NULL, 1),
(4574449, 658287, 19708, '<td valign="top">Very nicely done here. The background supports his environment well, and a great choice for black &amp; white. High marks from me on this one.</td>', 'Very nicely done here. The background supports his environment well, and a great choice for black & white. High marks from me on this one.', '2008-03-19 14:49:02.000000', NULL, 1),
(4574452, 657938, 89763, '<td valign="top">That tan definitely matches the environment</td>', 'That tan definitely matches the environment', '2008-03-19 14:49:44.000000', NULL, 1),
