(4577519, 658286, 83686, '<td valign="top">very focused, needed a bit more color in the picture but good none the less</td>', 'very focused, needed a bit more color in the picture but good none the less', '2008-03-20 18:15:09.000000', NULL, 1),
(4577520, 659511, 83686, '<td valign="top">good composition and focus, a bit on the bright side but very good otherwise</td>', 'good composition and focus, a bit on the bright side but very good otherwise', '2008-03-20 18:15:47.000000', NULL, 1),
(4577639, 659047, 59029, '<td valign="top">nice portrait but I''d like to see her surrounded by books, to drive home her bookwormishness.</td>', 'nice portrait but I''d like to see her surrounded by books, to drive home her bookwormishness.', '2008-03-20 19:48:40.000000', NULL, 1),
(4577641, 658625, 59029, '<td valign="top">mmm! Guinness!  Lovely shot the b/w really works well here, like that he''s concentrating on task at hand and not looking at pesky photog :-) 8</td>', 'mmm! Guinness!  Lovely shot the b/w really works well here, like that he''s concentrating on task at hand and not looking at pesky photog :-) 8', '2008-03-20 19:49:55.000000', NULL, 1),
(4577643, 658418, 59029, '<td valign="top">lighting''s a little hard but it may be all you had to work with, wish too her hand weren''t covering the mike, good try.</td>', 'lighting''s a little hard but it may be all you had to work with, wish too her hand weren''t covering the mike, good try.', '2008-03-20 19:50:49.000000', NULL, 1),
(4577648, 658968, 59029, '<td valign="top">yeah baby!  Gordon Ramsay eat yer f****in'' heart out!  excellent capture, I can smell singed hair from here, 8</td>', 'yeah baby!  Gordon Ramsay eat yer f****in'' heart out!  excellent capture, I can smell singed hair from here, 8', '2008-03-20 19:51:55.000000', NULL, 1),
(4577649, 659192, 59029, '<td valign="top">love the camo aspect but wish the flash weren''t reflected in eyes.  Good try.</td>', 'love the camo aspect but wish the flash weren''t reflected in eyes.  Good try.', '2008-03-20 19:52:41.000000', NULL, 1),
(4577650, 659461, 59029, '<td valign="top">great leading lines and reflection works well. 7</td>', 'great leading lines and reflection works well. 7', '2008-03-20 19:53:08.000000', NULL, 1),
(4577652, 659101, 59029, '<td valign="top">St Bernard on a sand dune, not a snowy Alp? :0  Different, like the untold story here.</td>', 'St Bernard on a sand dune, not a snowy Alp? :0  Different, like the untold story here.', '2008-03-20 19:54:06.000000', NULL, 1),
(4577654, 658404, 59029, '<td valign="top">a little too centred but amazing capture of tight formation, well done, 7</td>', 'a little too centred but amazing capture of tight formation, well done, 7', '2008-03-20 19:54:49.000000', NULL, 1),
(4577657, 658239, 59029, '<td valign="top">glare off robe to the right is distracting from the contrast between their faces.</td>', 'glare off robe to the right is distracting from the contrast between their faces.', '2008-03-20 19:55:41.000000', NULL, 1),
(4577658, 659383, 59029, '<td valign="top">coal miner? very gritty and real, yet very simple, 7</td>', 'coal miner? very gritty and real, yet very simple, 7', '2008-03-20 19:56:19.000000', NULL, 1),
(4577661, 658091, 59029, '<td valign="top">lol''d when I saw this, an old-time huckster still doing his job! I feel like he''s beckoning me over, 7</td>', 'lol''d when I saw this, an old-time huckster still doing his job! I feel like he''s beckoning me over, 7', '2008-03-20 19:57:20.000000', NULL, 1),
(4577663, 657185, 59029, '<td valign="top">unusual shot but very original. 8</td>', 'unusual shot but very original. 8', '2008-03-20 19:57:42.000000', NULL, 1),
(4577664, 659690, 59029, '<td valign="top">I feel detached here, if only one of them was looking at camera it would be much more engaging.</td>', 'I feel detached here, if only one of them was looking at camera it would be much more engaging.', '2008-03-20 19:58:24.000000', NULL, 1),
(4577665, 659545, 59029, '<td valign="top">lighting a little flat but you probably had little choice, engaging subject.</td>', 'lighting a little flat but you probably had little choice, engaging subject.', '2008-03-20 19:59:12.000000', NULL, 1),
(4577667, 659243, 59029, '<td valign="top">A little stopping down may have helped cut the glare.  Some odd pp on hand.</td>', 'A little stopping down may have helped cut the glare.  Some odd pp on hand.', '2008-03-20 20:00:11.000000', NULL, 1),
(4577670, 659182, 59029, '<td valign="top">I like this shot, I can feel a story here.  The pp treatment works well. 7</td>', 'I like this shot, I can feel a story here.  The pp treatment works well. 7', '2008-03-20 20:01:05.000000', NULL, 1),
(4577672, 659388, 59029, '<td valign="top">Usually eye contact with cam strengthens a shot but in this case it would weaken it, glad you got this with her concentrating on music. 8</td>', 'Usually eye contact with cam strengthens a shot but in this case it would weaken it, glad you got this with her concentrating on music. 8', '2008-03-20 20:02:01.000000', NULL, 1),
(4577675, 657935, 59029, '<td valign="top">interesting character, looks like he''s been at his job 30 yrs. 7</td>', 'interesting character, looks like he''s been at his job 30 yrs. 7', '2008-03-20 20:04:58.000000', NULL, 1),
(4577678, 659152, 59029, '<td valign="top">Very different, love the POV, comp, and expressions and the tossed head of the horse on the right. wish I could hear what was being said! 8</td>', 'Very different, love the POV, comp, and expressions and the tossed head of the horse on the right. wish I could hear what was being said! 8', '2008-03-20 20:06:08.000000', NULL, 1),
(4577679, 659546, 59029, '<td valign="top">I like the way the face is eliminated here by the glare of lights, backdrop and camera.  Wish I had that setup! 7</td>', 'I like the way the face is eliminated here by the glare of lights, backdrop and camera.  Wish I had that setup! 7', '2008-03-20 20:06:53.000000', NULL, 1),
(4577681, 658986, 59029, '<td valign="top">looks like he''s on an old Roman road in UK. 7</td>', 'looks like he''s on an old Roman road in UK. 7', '2008-03-20 20:07:32.000000', NULL, 1),
(4577683, 659361, 59029, '<td valign="top">hahaha!  Though the extreme closeup isn''t flattering, Frankie looks like a pleasant and hardworking soul.  Shadow on face a little harsh. 7</td>', 'hahaha!  Though the extreme closeup isn''t flattering, Frankie looks like a pleasant and hardworking soul.  Shadow on face a little harsh. 7', '2008-03-20 20:08:52.000000', NULL, 1),
(4577685, 659670, 59029, '<td valign="top">hmm..trying to get a sense of story here...the dead rose and her black clothing may indicate mourning or neglect.  Hard to tell.</td>', 'hmm..trying to get a sense of story here...the dead rose and her black clothing may indicate mourning or neglect.  Hard to tell.', '2008-03-20 20:09:51.000000', NULL, 1),
(4577689, 658684, 59029, '<td valign="top">good shot, a little grainy though.</td>', 'good shot, a little grainy though.', '2008-03-20 20:10:52.000000', NULL, 1),
(4577690, 659260, 16106, '<td valign="top">good colors , but there just isnt enough of the subject in the frame for me, I do like the second image of him in the mirrors but the fellow seems a bit lost in his enviroment.</td>', 'good colors , but there just isnt enough of the subject in the frame for me, I do like the second image of him in the mirrors but the fellow seems a bit lost in his enviroment.', '2008-03-20 20:11:11.000000', NULL, 1),
(4577691, 659146, 59029, '<td valign="top">a little too much glare but interesting subject, looks like he''s done well for himself. 7</td>', 'a little too much glare but interesting subject, looks like he''s done well for himself. 7', '2008-03-20 20:12:11.000000', NULL, 1),
(4577692, 658474, 59029, '<td valign="top">good idea but too ambiguous.</td>', 'good idea but too ambiguous.', '2008-03-20 20:12:34.000000', NULL, 1),
(4577693, 659543, 59029, '<td valign="top">Now here''s a bookworm!  The focus is a bit soft and lighting''s not in your favour but she reminds me of me at her age, buried in the library, though back then we didn''t have Captain Underpants! 7</td>', 'Now here''s a bookworm!  The focus is a bit soft and lighting''s not in your favour but she reminds me of me at her age, buried in the library, though back then we didn''t have Captain Underpants! 7', '2008-03-20 20:13:49.000000', NULL, 1),
(4577694, 657629, 16106, '<td valign="top">i like the way the blues tie the horse and rider together from halter to clothing, but i wish the girl had a bit more prominence in the image, I am assuming that the portrait is of her and not the horse, so I may be off in that assessment. lovely textures and expressions.</td>', 'i like the way the blues tie the horse and rider together from halter to clothing, but i wish the girl had a bit more prominence in the image, I am assuming that the portrait is of her and not the horse, so I may be off in that assessment. lovely textures and expressions.', '2008-03-20 20:13:50.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4577695, 658717, 59029, '<td valign="top">very gritty and real, even if it is just a training day. 7</td>', 'very gritty and real, even if it is just a training day. 7', '2008-03-20 20:14:20.000000', NULL, 1),
(4577697, 659632, 59029, '<td valign="top">too much glare, too much profile, not enough sense of place.</td>', 'too much glare, too much profile, not enough sense of place.', '2008-03-20 20:14:49.000000', NULL, 1),
(4577701, 659443, 59029, '<td valign="top">haha! love shots like this - tilted horizon, weird lightihg and strange setup. 7</td>', 'haha! love shots like this - tilted horizon, weird lightihg and strange setup. 7', '2008-03-20 20:15:27.000000', NULL, 1),
(4577702, 659236, 59029, '<td valign="top">very nice and soft but a tiny bit too posed with the bottle, I''d''ve just left in the stuffie. 7</td>', 'very nice and soft but a tiny bit too posed with the bottle, I''d''ve just left in the stuffie. 7', '2008-03-20 20:16:14.000000', NULL, 1),
(4577704, 659688, 16106, '<td valign="top">Great action shot, crisp and strong colors. The post precessing seems a touch overdone, given the stron light the shadow areas are a bit flat losing some of the modeling of the light, he looks a touch too silloetted. Minor quible, and it would make a great promotional shot.</td>', 'Great action shot, crisp and strong colors. The post precessing seems a touch overdone, given the stron light the shadow areas are a bit flat losing some of the modeling of the light, he looks a touch too silloetted. Minor quible, and it would make a great promotional shot.', '2008-03-20 20:16:59.000000', NULL, 1),
(4577709, 658115, 59029, '<td valign="top">unusual shot, I like the pensive look on boy''s face, his placement on the shore and the sweater/cap. 8</td>', 'unusual shot, I like the pensive look on boy''s face, his placement on the shore and the sweater/cap. 8', '2008-03-20 20:18:35.000000', NULL, 1),
(4577711, 659257, 59029, '<td valign="top">what a cutie!  I like the androgynous aspect to his face.  reminds me of a young Jim Morrison. 7</td>', 'what a cutie!  I like the androgynous aspect to his face.  reminds me of a young Jim Morrison. 7', '2008-03-20 20:19:55.000000', NULL, 1),
(4577712, 659515, 16106, '<td valign="top">Nice dynamic framing and I like the underlighting on the modle in contrast with the down lighting of the backround, but the highlights on her face are a bit blown on my monitor.</td>', 'Nice dynamic framing and I like the underlighting on the modle in contrast with the down lighting of the backround, but the highlights on her face are a bit blown on my monitor.', '2008-03-20 20:20:19.000000', NULL, 1),
(4577714, 658143, 59029, '<td valign="top">nice play on town crier, love the sign advertising mushy peas!  Must be Sheffield! 7</td>', 'nice play on town crier, love the sign advertising mushy peas!  Must be Sheffield! 7', '2008-03-20 20:21:24.000000', NULL, 1),
(4577716, 659105, 16106, '<td valign="top">The crop on both his head and the grill seem too tight. I really like the way you got the light across his sholder, but elsewhere it seems rather flat.</td>', 'The crop on both his head and the grill seem too tight. I really like the way you got the light across his sholder, but elsewhere it seems rather flat.', '2008-03-20 20:23:01.000000', NULL, 1),
(4577718, 658239, 16106, '<td valign="top">Great capture, and nice DOF, but for this challenge i wish I could see a bit more of where they are.</td>', 'Great capture, and nice DOF, but for this challenge i wish I could see a bit more of where they are.', '2008-03-20 20:23:55.000000', NULL, 1),
(4577719, 657629, 59029, '<td valign="top">I''m a horsewoman by profession, so the halter strikes me as too small...and though I guess leadshank is meant to convey horse/rider link, it just doesn''t work for me.  But there is true love in the girl''s eyes and that matters most. 7</td>', 'I''m a horsewoman by profession, so the halter strikes me as too small...and though I guess leadshank is meant to convey horse/rider link, it just doesn''t work for me.  But there is true love in the girl''s eyes and that matters most. 7', '2008-03-20 20:24:13.000000', NULL, 1),
(4577721, 659231, 59029, '<td valign="top">terrific use of thirds, weary urban commuter catching some zzzs on the way in, 7</td>', 'terrific use of thirds, weary urban commuter catching some zzzs on the way in, 7', '2008-03-20 20:24:56.000000', NULL, 1),
(4577722, 659162, 59029, '<td valign="top">whoa! definitely an enviromental element here.</td>', 'whoa! definitely an enviromental element here.', '2008-03-20 20:25:36.000000', NULL, 1),
(4577723, 658972, 59029, '<td valign="top">watching intently for his cue, holding his breath  - 7</td>', 'watching intently for his cue, holding his breath  - 7', '2008-03-20 20:26:18.000000', NULL, 1),
(4577724, 659300, 59029, '<td valign="top">would love to see a face here.</td>', 'would love to see a face here.', '2008-03-20 20:26:43.000000', NULL, 1),
(4577726, 659243, 16106, '<td valign="top">Im not sure what that thing in the upper left corner is, but should something on the undercarrige have such lovely colors? Might be a bit blown on the highlights of the hand and chin, but the framing, and mostly the expression you got in his eyes, make this my favorite so far.</td>', 'Im not sure what that thing in the upper left corner is, but should something on the undercarrige have such lovely colors? Might be a bit blown on the highlights of the hand and chin, but the framing, and mostly the expression you got in his eyes, make this my favorite so far.', '2008-03-20 20:27:07.000000', NULL, 1),
(4577729, 659470, 16106, '<td valign="top">Lovely colors, and great framing along the center axis. I really like this image. Some of the other very good portraits in this challenge dont have enough environment, this one suffers from too much environment, and almost no face or expression. While this framing makes it a very stong shot, it loses a point or so for not being as good a challenge entry as it does a composition.</td>', 'Lovely colors, and great framing along the center axis. I really like this image. Some of the other very good portraits in this challenge dont have enough environment, this one suffers from too much environment, and almost no face or expression. While this framing makes it a very stong shot, it loses a point or so for not being as good a challenge entry as it does a composition.', '2008-03-20 20:31:43.000000', NULL, 1),
(4577733, 659235, 16106, '<td valign="top">This looks a bit backfocused; I see good defiition on the bushes and ferns behind the subject, but the beak and eye of the emu are a bit soft.</td>', 'This looks a bit backfocused; I see good defiition on the bushes and ferns behind the subject, but the beak and eye of the emu are a bit soft.', '2008-03-20 20:34:09.000000', NULL, 1),
(4577741, 658793, 16106, '<td valign="top">Great bird shot, strong use of diagonal framing, and good sharpness , especially nice textures on the downy belly feathers, but it seems a bit shoehorned into this challenge.</td>', 'Great bird shot, strong use of diagonal framing, and good sharpness , especially nice textures on the downy belly feathers, but it seems a bit shoehorned into this challenge.', '2008-03-20 20:36:59.000000', NULL, 1),
(4577744, 659383, 16106, '<td valign="top">The only envornment in the shot is the smutz on the fellow''s face, but it is a lovely shot, well lit and the uniformity of grtty textues from his facial hair to the scratches on his hard hat make this a very strong portrait.</td>', 'The only envornment in the shot is the smutz on the fellow''s face, but it is a lovely shot, well lit and the uniformity of grtty textues from his facial hair to the scratches on his hard hat make this a very strong portrait.', '2008-03-20 20:39:46.000000', NULL, 1),
(4577746, 657504, 16106, '<td valign="top">very nice shot, and a good subject well captured. the difference between this and my favorites in the challenge is that here I get no strong sense of how this fellow interacts with this particular environment.</td>', 'very nice shot, and a good subject well captured. the difference between this and my favorites in the challenge is that here I get no strong sense of how this fellow interacts with this particular environment.', '2008-03-20 20:43:02.000000', NULL, 1),
(4577747, 657629, 81964, '<td valign="top">In my top 3 of this challenge. Great exposure and love how the horses eye captures your attention</td>', 'In my top 3 of this challenge. Great exposure and love how the horses eye captures your attention', '2008-03-20 20:44:42.000000', NULL, 1),
(4577754, 659203, 16106, '<td valign="top">I feel I ought to like this shot more than I do, the framing and the balance of subject and environment are perfect, but from her clothing to her searching the distance expression, she looks about as detached from the environment of a chemestry lab as it is possible. This would be a fine entry for a fashion challenge, but in this one the integration of portrait and environment are the key element.</td>', 'I feel I ought to like this shot more than I do, the framing and the balance of subject and environment are perfect, but from her clothing to her searching the distance expression, she looks about as detached from the environment of a chemestry lab as it is possible. This would be a fine entry for a fashion challenge, but in this one the integration of portrait and environment are the key element.', '2008-03-20 20:49:02.000000', NULL, 1),
(4577761, 659257, 16106, '<td valign="top">I know this is knitpicking, but as someone who swings a hammer for a living the model''s wearing of a lose chain on the hand he is holding the hammer in bothers me. In a glance it tells me that this is a fellow who is not a carpenter, or if he is he would be told to take the bloody thing off before he did himself a serious injury on any real job site. Between the movement of the chain, and the risk of it hanging up on something he would have no skin on that wrist if he swung a hammer with it on for two hours.<br/> <br/> you got a nice soulfull expression here, and the duotone processing suits it well. the framing creates a nice intimacy but the cropping of the hammer, the symbol of the stated profession, draws the eye off the page.</td>', 'I know this is knitpicking, but as someone who swings a hammer for a living the model''s wearing of a lose chain on the hand he is holding the hammer in bothers me. In a glance it tells me that this is a fellow who is not a carpenter, or if he is he would be told to take the bloody thing off before he did himself a serious injury on any real job site. Between the movement of the chain, and the risk of it hanging up on something he would have no skin on that wrist if he swung a hammer with it on for two hours.  you got a nice soulfull expression here, and the duotone processing suits it well. the framing creates a nice intimacy but the cropping of the hammer, the symbol of the stated profession, draws the eye off the page.', '2008-03-20 20:58:54.000000', NULL, 1),
(4577764, 659231, 16106, '<td valign="top">Strangely evocative feel here. The use of B&amp;W allows an abstraction that lets the strong division of the inner and outer environments play against each other, and the feeling of meloncholy "alone in the crowd" vibe work well. That said, no face, no eyes, no pretty colors, the voters should hammer you. Dont let that stop you, this is a nice peice of work.</td>', 'Strangely evocative feel here. The use of B&W allows an abstraction that lets the strong division of the inner and outer environments play against each other, and the feeling of meloncholy "alone in the crowd" vibe work well. That said, no face, no eyes, no pretty colors, the voters should hammer you. Dont let that stop you, this is a nice peice of work.', '2008-03-20 21:03:07.000000', NULL, 1),
(4577766, 659245, 16106, '<td valign="top">wow. so far the best integration of subject and environment, and the strong lateral composition is great.</td>', 'wow. so far the best integration of subject and environment, and the strong lateral composition is great.', '2008-03-20 21:06:50.000000', NULL, 1),
(4577771, 659666, 19572, '<td valign="top">Interesting colors, this almost looks HDR.  A bit noisy in the upper right, but overall a nice shot.</td>', 'Interesting colors, this almost looks HDR.  A bit noisy in the upper right, but overall a nice shot.', '2008-03-20 21:08:44.000000', NULL, 1),
(4577777, 658985, 19572, '<td valign="top">I hope she at least puts her hands on the wheel some of the time :)</td>', 'I hope she at least puts her hands on the wheel some of the time :)', '2008-03-20 21:09:56.000000', NULL, 1),
(4577780, 657575, 16106, '<td valign="top">Great composition, and the contratst between the loose arms of the workmen and the coil of tubing is particularly strong. The processing however seems heavy handed, with a huge fall off in light on the edges, if you didnt burn the edges here you might want to check your sensor.</td>', 'Great composition, and the contratst between the loose arms of the workmen and the coil of tubing is particularly strong. The processing however seems heavy handed, with a huge fall off in light on the edges, if you didnt burn the edges here you might want to check your sensor.', '2008-03-20 21:10:30.000000', NULL, 1),
(4577782, 659257, 19572, '<td valign="top">Very nice shot.</td>', 'Very nice shot.', '2008-03-20 21:12:15.000000', NULL, 1),
(4577786, 659146, 19572, '<td valign="top">What is his environment?  Maybe show a bit more of the background so we can see what it''s all about.</td>', 'What is his environment?  Maybe show a bit more of the background so we can see what it''s all about.', '2008-03-20 21:13:55.000000', NULL, 1),
(4577790, 659515, 19572, '<td valign="top">I like this one. The movement of the people in the background adds a nice effect.</td>', 'I like this one. The movement of the people in the background adds a nice effect.', '2008-03-20 21:15:32.000000', NULL, 1),
(4577798, 659210, 16106, '<td valign="top">One of the best examples of a subject in their environment so far, i just wish that the DOF was a bit wider, his face, the key element in any portrait lacks the sharpness of his hands and the rack of tubes.</td>', 'One of the best examples of a subject in their environment so far, i just wish that the DOF was a bit wider, his face, the key element in any portrait lacks the sharpness of his hands and the rack of tubes.', '2008-03-20 21:17:56.000000', NULL, 1),
(4577809, 659072, 16106, '<td valign="top">What a find! I wish you had a bit more light in the shadows of his face, but his is a great entry, the limited color palate helps the feel.</td>', 'What a find! I wish you had a bit more light in the shadows of his face, but his is a great entry, the limited color palate helps the feel.', '2008-03-20 21:23:06.000000', NULL, 1),
(4577814, 658907, 16106, '<td valign="top">No mic, no stage, no audience, no environment. Techniclaay strong image, but...</td>', 'No mic, no stage, no audience, no environment. Techniclaay strong image, but...', '2008-03-20 21:24:27.000000', NULL, 1),
(4577821, 658829, 16106, '<td valign="top">i like the rather scary colors here but this is cleary either not a teenager or this is not her room, it is far too tidy.</td>', 'i like the rather scary colors here but this is cleary either not a teenager or this is not her room, it is far too tidy.', '2008-03-20 21:26:13.000000', NULL, 1),
(4577827, 659359, 16106, '<td valign="top">Wow great bug shot, but I think it would have done better in Harsh Environment than in portrait. It is an amazing image, just not a good challenge entry.</td>', 'Wow great bug shot, but I think it would have done better in Harsh Environment than in portrait. It is an amazing image, just not a good challenge entry.', '2008-03-20 21:29:00.000000', NULL, 1),
(4577836, 659217, 16106, '<td valign="top">Stong lighting, good colors, but couldn''t you have found somewhere to shoot without that pole to the right and the wires running across the backround? This would have been a much better shot on an empty road or a flat plain than here. this bike rider''s environment is the distant horizon, not the garage.</td>', 'Stong lighting, good colors, but couldn''t you have found somewhere to shoot without that pole to the right and the wires running across the backround? This would have been a much better shot on an empty road or a flat plain than here. this bike rider''s environment is the distant horizon, not the garage.', '2008-03-20 21:33:10.000000', NULL, 1),
(4577924, 659257, 77724, '<td valign="top">Nice tone to this, would like better if his face was not blocked so much - my eyes went right to the hammer handle</td>', 'Nice tone to this, would like better if his face was not blocked so much - my eyes went right to the hammer handle', '2008-03-20 22:53:14.000000', NULL, 1),
(4577925, 659677, 77724, '<td valign="top">I thnik more DOF would work better for this challenge</td>', 'I thnik more DOF would work better for this challenge', '2008-03-20 22:53:47.000000', NULL, 1),
(4577926, 659048, 77724, '<td valign="top">cute</td>', 'cute', '2008-03-20 22:54:03.000000', NULL, 1),
(4577929, 659182, 77724, '<td valign="top">really captures the feeling - i like this a lot</td>', 'really captures the feeling - i like this a lot', '2008-03-20 22:55:04.000000', NULL, 1),
