(4579453, 658342, 90380, '<td valign="top">Great portrait! But I don''t see her environment at all, so I''m afraid it doesn''t really meet the challenge.</td>', 'Great portrait! But I don''t see her environment at all, so I''m afraid it doesn''t really meet the challenge.', '2008-03-21 22:41:11.000000', NULL, 1),
(4579464, 658985, 18367, '<td valign="top">I most certainly hope she is stopped... lest she become a casualty.</td>', 'I most certainly hope she is stopped... lest she become a casualty.', '2008-03-21 22:53:25.000000', NULL, 1),
