(4580572, 659260, 76335, '<td valign="top">Excellent point of view. A seven for you.</td>', 'Excellent point of view. A seven for you.', '2008-03-22 20:31:07.000000', NULL, 1),
(4580573, 659477, 76335, '<td valign="top">Brilliant to capture a portrait at this angle. An eight for you.</td>', 'Brilliant to capture a portrait at this angle. An eight for you.', '2008-03-22 20:31:21.000000', NULL, 1),
(4580575, 659171, 76335, '<td valign="top">Absolutely brilliant. A nine for you.</td>', 'Absolutely brilliant. A nine for you.', '2008-03-22 20:31:43.000000', NULL, 1),
