(4580577, 658972, 76335, '<td valign="top">Terrific. A nine for you.</td>', 'Terrific. A nine for you.', '2008-03-22 20:32:09.000000', NULL, 1),
(4580578, 659182, 76335, '<td valign="top">Excellent. Is this a candid? Curious to know how you shot this. An eight for you.</td>', 'Excellent. Is this a candid? Curious to know how you shot this. An eight for you.', '2008-03-22 20:32:20.000000', NULL, 1),
(4580579, 659236, 76335, '<td valign="top">The lighting and colors are exquisite. (I believe that''s the first time I''ve felt compelled to use "exquisite" in a comment.) An eight for you.</td>', 'The lighting and colors are exquisite. (I believe that''s the first time I''ve felt compelled to use "exquisite" in a comment.) An eight for you.', '2008-03-22 20:32:34.000000', NULL, 1),
(4580580, 659610, 76335, '<td valign="top">Great use of leading lines. Nice angle and exposure time also. An eight for you.</td>', 'Great use of leading lines. Nice angle and exposure time also. An eight for you.', '2008-03-22 20:32:44.000000', NULL, 1),
(4580581, 659551, 76335, '<td valign="top">Terrific framing. I almost jumped when I finally spotted him. A seven for you.</td>', 'Terrific framing. I almost jumped when I finally spotted him. A seven for you.', '2008-03-22 20:32:52.000000', NULL, 1),
