(4585553, 657707, 61958, '<td valign="top">nice wildlife shot</td>', 'nice wildlife shot', '2008-03-25 11:39:45.000000', NULL, 1),
(4585555, 659443, 61958, '<td valign="top">very interesting photo... I like it</td>', 'very interesting photo... I like it', '2008-03-25 11:40:01.000000', NULL, 1),
