INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4587471, 658287, 53147, '<td valign="top">Well done. This was one of my highest rated. COngrats!</td>', 'Well done. This was one of my highest rated. COngrats!', '2008-03-26 01:33:39.000000', NULL, 0),
(4587490, 658826, 10080, '<td valign="top">It had been a while since I have entered a contest. I was finally getting the itch again. This site has really taught me so much. I entered this portrait, because it was what I had from the weekend that I REALLY liked. I knew in the mind of alot of viewers it wouldnt be considered as "environmental" but I though that a few would get it? I am not dissapointed in the score, or the comments. I love the shot! I am happy. I actually did think that the environment fit pretty well in the shot? Those "Spring Flowers" as we call them.....are a huge part of an environment in the spring in Kentucky. But I didnt think worldwide.....I thought local? I still thank you for all your comments, and I learned something. The pic needs to be universal. That makes sense. Congrats to the winners! They were wonderful!<br/>B</td>', 'It had been a while since I have entered a contest. I was finally getting the itch again. This site has really taught me so much. I entered this portrait, because it was what I had from the weekend that I REALLY liked. I knew in the mind of alot of viewers it wouldnt be considered as "environmental" but I though that a few would get it? I am not dissapointed in the score, or the comments. I love the shot! I am happy. I actually did think that the environment fit pretty well in the shot? Those "Spring Flowers" as we call them.....are a huge part of an environment in the spring in Kentucky. But I didnt think worldwide.....I thought local? I still thank you for all your comments, and I learned something. The pic needs to be universal. That makes sense. Congrats to the winners! They were wonderful!B', '2008-03-26 01:44:20.000000', NULL, 0),
(4587495, 658287, 52549, '<td valign="top">WTG, Sean! Two great models and a wonderful image. Love the b/w tones. Big congrats on your ribbon.</td>', 'WTG, Sean! Two great models and a wonderful image. Love the b/w tones. Big congrats on your ribbon.', '2008-03-26 01:53:22.000000', NULL, 0),
